using System;using System.IO;using System.Linq;using System.Net;using System.Text;using System.Threading;using System.Collections.Generic;
namespace KlipperWinForms {using Obj=Dictionary<string,object>;
 sealed class Versions {
  public string Root,Project,Repository;Action<string> Log;
  readonly HashSet<string> progressFiles=new HashSet<string>(),finishedFiles=new HashSet<string>();
  void FileProgress(){Log("@@DOWNLOAD_PROGRESS@@"+finishedFiles.Count+"/"+progressFiles.Count);}
  public Versions(string project,Action<string> log){Project=project;Root=Path.Combine(U.Root,project=="katapult"?"Katapult":"Klipper");Repository=project=="katapult"?"Arksine/katapult":"Klipper3d/klipper";Log=log;Directory.CreateDirectory(Root);Directory.CreateDirectory(Path.Combine(Root,"_metadata"));ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;}
  public static string Label(Obj v){string label=Json.S(v,"git_describe");if(label!="")return label;string r=Json.S(v,"ref"),sha=Json.S(v,"sha");return System.Text.RegularExpressions.Regex.IsMatch(r,@"^v\d+\.\d+\.\d+$")?r+"-0-g"+sha.Substring(0,8):sha.Substring(0,8);}
  object Api(string route,string key,bool immutable=false){string cache=Path.Combine(Root,"_metadata",key+".json");Obj saved=File.Exists(cache)?U.Read(cache):null;if(immutable&&saved!=null)return saved["data"];var req=(HttpWebRequest)WebRequest.Create("https://api.github.com/repos/"+Repository+"/"+route);req.UserAgent="KlipperFirmwareWizard/1.0";req.Accept="application/vnd.github+json";req.Timeout=20000;if(saved!=null&&Json.S(saved,"etag")!="")req.Headers[HttpRequestHeader.IfNoneMatch]=Json.S(saved,"etag");try{using(var response=(HttpWebResponse)req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){object data=Json.Serializer().DeserializeObject(reader.ReadToEnd());U.Write(cache,new Obj{{"data",data},{"etag",response.Headers["ETag"]},{"checked_at",DateTime.UtcNow.ToString("o")}});return data;}}catch(WebException ex){if(ex.Response is HttpWebResponse r&&r.StatusCode==HttpStatusCode.NotModified&&saved!=null)return saved["data"];if(ex.Response is HttpWebResponse quota&&(quota.StatusCode==(HttpStatusCode)429||quota.StatusCode==HttpStatusCode.Forbidden&&quota.Headers["X-RateLimit-Remaining"]=="0"))throw new GitHubQuotaException(quota.Headers["X-RateLimit-Reset"],ex);throw new Exception("GitHub 메타데이터 조회 오류: "+ex.Message,ex);}}
  Obj Compare(string a,string b)=>(Obj)Api("compare/"+a+"..."+b+"?per_page=1&page=2","compare-"+a+"-"+b,true);
  Obj Describe(Obj v,List<Obj> tags){string sha=Json.S(v,"sha");string fp=U.Hash(Encoding.UTF8.GetBytes("["+string.Join(", ",tags.OrderBy(t=>Json.S(t,"name"),StringComparer.Ordinal).Select(t=>"["+Json.Write(Json.S(t,"name"))+", "+Json.Write(Json.S(Json.D(t,"commit"),"sha"))+"]"))+"]"));string file=Path.Combine(Root,"_metadata","describe-"+sha+".json");Obj description=null;
   if(File.Exists(file)){var cached=U.Read(file);if(Json.S(cached,"tag_fingerprint")==fp)description=Json.D(cached,"description");}
   if(description==null){Obj best=tags.FirstOrDefault(t=>Json.S(Json.D(t,"commit"),"sha")==sha);long count=best==null?long.MaxValue:0;if(best==null)foreach(var t in tags){if(best!=null){var ancestor=Compare(Json.S(Json.D(t,"commit"),"sha"),Json.S(Json.D(best,"commit"),"sha"));if(new[]{"ahead","identical"}.Contains(Json.S(ancestor,"status"))&&Convert.ToInt64(ancestor["behind_by"])==0)continue;}var result=Compare(Json.S(Json.D(t,"commit"),"sha"),sha);if(new[]{"ahead","identical"}.Contains(Json.S(result,"status"))&&Convert.ToInt64(result["behind_by"])==0&&Convert.ToInt64(result["ahead_by"])<count){best=t;count=Convert.ToInt64(result["ahead_by"]);}}
    description=new Obj{{"git_describe",best==null?sha.Substring(0,8):Json.S(best,"name")+"-"+count+"-g"+sha.Substring(0,8)},{"base_tag",best==null?null:best["name"]},{"commit_count",best==null?(object)null:count}};U.Write(file,new Obj{{"sha",sha},{"tag_fingerprint",fp},{"description",description}});}
   foreach(var p in description)v[p.Key]=p.Value;return v;
  }
  public Obj Catalog(bool online){string file=Path.Combine(Root,"catalog.json");if(!online)return File.Exists(file)?U.Read(file):new Obj{{"versions",new object[0]}};
   var head=(Obj)Api("commits/master","latest");var tags=new List<Obj>();for(int page=1;;page++){var batch=((object[])Api("tags?per_page=100"+(page==1?"":"&page="+page),page==1?"tags":"tags-"+page)).Cast<Obj>().ToList();tags.AddRange(batch);if(batch.Count<100)break;}
   var versions=new List<Obj>{Describe(new Obj{{"ref","master"},{"sha",head["sha"]},{"date",Json.D(Json.D(head,"commit"),"committer")["date"]}},tags)};versions.AddRange(tags.Select(t=>Describe(new Obj{{"ref",t["name"]},{"sha",Json.D(t,"commit")["sha"]}},tags)));var data=new Obj{{"latest",versions[0]},{"versions",versions.Cast<object>().ToArray()},{"live",true},{"checked_at",DateTime.UtcNow.ToString("o")}};U.Write(file,data);return data;
  }
  public List<Obj> All(){var list=Json.Rows(Catalog(false),"versions").Select(v=>new Obj(v)).ToList();foreach(var path in Directory.GetDirectories(Root).Select(d=>Path.Combine(d,"version.json")).Where(File.Exists)){var v=U.Read(path);var existing=list.FirstOrDefault(x=>Json.S(x,"sha")==Json.S(v,"sha"));if(existing==null)list.Add(v);else foreach(string key in new[]{"date","date_kind","config_ready"})if(v.ContainsKey(key))existing[key]=v[key];}return list;}
  void ReadDate(Obj version){
   if(Json.S(version,"date_kind")!="")return;
   if(Json.S(version,"ref").StartsWith("v",StringComparison.Ordinal))try{var release=(Obj)Api("releases/tags/"+Uri.EscapeDataString(Json.S(version,"ref")),"release-"+Json.S(version,"sha"),true);string date=Json.S(release,"published_at");if(date!=""){version["date"]=date;version["date_kind"]="release";return;}}catch(Exception){ }
   if(Json.S(version,"date")=="")try{var commit=(Obj)Api("commits/"+Json.S(version,"sha"),"commit-date-"+Json.S(version,"sha"),true);version["date"]=Json.S(Json.D(Json.D(commit,"commit"),"committer"),"date");}catch(Exception){ }
   if(Json.S(version,"date")!="")version["date_kind"]="commit";
  }
  public string Folder(Obj v)=>U.SafePath(Root,Label(v));
  public Dictionary<string,Obj> Tree(Obj v){var data=(Obj)Api("git/trees/"+Json.S(v,"sha")+"?recursive=1","tree-"+Json.S(v,"sha"),true);if(Json.B(data,"truncated"))throw new Exception("Truncated Git tree");return Json.Rows(data,"tree").Where(e=>Json.S(e,"type")=="blob"&&Json.S(e,"mode")!="120000").ToDictionary(e=>Json.S(e,"path"));}
  public void Fetch(Obj v,IEnumerable<string> names,Dictionary<string,Obj> tree){var files=names.Distinct().ToArray();string revision=Json.S(v,"sha")+":";foreach(string file in files)progressFiles.Add(revision+file);FileProgress();string folder=Folder(v);Directory.CreateDirectory(folder);foreach(string name in files){if(!tree.ContainsKey(name)||name.Contains(":")||name.Split('/').Contains(".."))throw new Exception("Invalid source path: "+name);string dest=U.SafePath(folder,name),sha=Json.S(tree[name],"sha");if(File.Exists(dest)&&U.Blob(File.ReadAllBytes(dest))==sha){finishedFiles.Add(revision+name);FileProgress();continue;}byte[] data=null;
    foreach(var candidate in Directory.GetDirectories(Root).Select(d=>Path.Combine(d,name))){if(File.Exists(candidate)){var bytes=File.ReadAllBytes(candidate);if(U.Blob(bytes)==sha){data=bytes;break;}}}
    if(data==null){Log("다운로드: "+name);using(var client=new WebClient()){client.Headers["User-Agent"]="KlipperFirmwareWizard/1.0";data=client.DownloadData("https://raw.githubusercontent.com/"+Repository+"/"+Json.S(v,"sha")+"/"+name);}}
    if(U.Blob(data)!=sha)throw new Exception("Git blob hash mismatch: "+name);Directory.CreateDirectory(Path.GetDirectoryName(dest));string temp=dest+"."+Guid.NewGuid().ToString("N")+".part";File.WriteAllBytes(temp,data);if(File.Exists(dest))File.Delete(dest);File.Move(temp,dest);finishedFiles.Add(revision+name);FileProgress();
   }}
  public string Prepare(Obj v){var tree=Tree(v);Fetch(v,tree.Keys.Where(n=>n=="Makefile"||n=="COPYING"||n=="LICENSE"||n.StartsWith("src/")&&(n.EndsWith("Kconfig")||n.EndsWith("Makefile"))),tree);var info=new Obj(v);ReadDate(info);info["repository"]=Repository;info["config_ready"]=true;U.Write(Path.Combine(Folder(v),"version.json"),info);return Folder(v);}
 }
}
